-- ===================================================================
-- WebGIS Simulasi Genangan Banjir Kota Singkawang
-- Skema database + data spasial (hasil konversi shapefile ArcMap)
-- Catatan: sintaks kolom memakai "GEOMETRY_TYPE NOT NULL" (bukan
-- "GEOMETRY_TYPE SRID 4326 NOT NULL") agar kompatibel dengan MariaDB
-- bawaan XAMPP; SRID tetap dipakai lewat ST_GeomFromText(wkt, 4326).
-- Jalankan file ini di phpMyAdmin (tab Import) atau via:
--   mysql -u root -p < schema.sql
-- ===================================================================

DROP DATABASE IF EXISTS webgis_banjir_singkawang;
CREATE DATABASE webgis_banjir_singkawang CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE webgis_banjir_singkawang;

-- -------------------------------------------------------------
-- Tabel: genangan_banjir
-- Poligon area genangan per level ketinggian (hasil Raster to Polygon)
-- -------------------------------------------------------------
CREATE TABLE genangan_banjir (
    id INT AUTO_INCREMENT PRIMARY KEY,
    level_meter DECIMAL(3,1) NOT NULL COMMENT 'Ketinggian genangan dalam meter',
    nama VARCHAR(100) NOT NULL,
    warna_hex VARCHAR(7) NOT NULL COMMENT 'Warna representasi level pada peta (gradasi hijau-kuning-merah)',
    luas_km2 DECIMAL(10,2) DEFAULT NULL COMMENT 'Luas area genangan hasil kalkulasi geometri (proyeksi UTM 49N), estimasi otomatis',
    keterangan VARCHAR(255) DEFAULT NULL,
    geom MULTIPOLYGON NOT NULL,
    dibuat_pada TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    SPATIAL INDEX idx_genangan_geom (geom)
) ENGINE=InnoDB;

-- -------------------------------------------------------------
-- Tabel: batas_kota
-- -------------------------------------------------------------
CREATE TABLE batas_kota (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nama VARCHAR(100) NOT NULL,
    geom MULTIPOLYGON NOT NULL,
    SPATIAL INDEX idx_batas_kota_geom (geom)
) ENGINE=InnoDB;

-- -------------------------------------------------------------
-- Tabel: kecamatan
-- Catatan: shapefile sumber tidak menyertakan file .dbf (atribut),
-- sehingga nama kecamatan diisi generik ("Kecamatan 1", dst).
-- Silakan UPDATE tabel ini bila data atribut asli tersedia.
-- -------------------------------------------------------------
CREATE TABLE kecamatan (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nama VARCHAR(100) NOT NULL,
    geom MULTIPOLYGON NOT NULL,
    SPATIAL INDEX idx_kecamatan_geom (geom)
) ENGINE=InnoDB;

-- -------------------------------------------------------------
-- Tabel: batas_administrasi (garis batas kecamatan/kota)
-- -------------------------------------------------------------
CREATE TABLE batas_administrasi (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nama VARCHAR(100) NOT NULL,
    geom MULTILINESTRING NOT NULL,
    SPATIAL INDEX idx_batas_admin_geom (geom)
) ENGINE=InnoDB;

-- -------------------------------------------------------------
-- Tabel: danau (badan air / danau)
-- -------------------------------------------------------------
CREATE TABLE danau (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nama VARCHAR(100) NOT NULL,
    geom MULTIPOLYGON NOT NULL,
    SPATIAL INDEX idx_danau_geom (geom)
) ENGINE=InnoDB;

